<?php
namespace ZCCNG;if(!defined('ABSPATH'))exit;
final class Admin{
 private static $instance;public static function instance(){if(!self::$instance){self::$instance=new self();self::$instance->hooks();}return self::$instance;}
 private function hooks(){add_action('admin_menu',[$this,'menus'],20);add_action('network_admin_menu',[$this,'menus'],20);add_action('network_admin_menu',[$this,'settings_menu']);add_action('admin_enqueue_scripts',[$this,'assets']);add_action('admin_menu',[$this,'immersive'],9999);add_action('admin_bar_menu',[$this,'admin_bar'],9999);add_action('admin_init',[$this,'dashboard_redirect']);add_filter('login_redirect',[$this,'login_redirect'],50,3);add_action('network_admin_edit_zccng_save_settings',[$this,'save_settings']);add_action('admin_init',[$this,'track_activity'],2);add_action('wp_login',[$this,'track_login'],10,2);}
 public function track_login($login,$user){Audit::log('login','User logged in',['user_id'=>$user->ID]);}public function track_activity(){if(is_user_logged_in())update_user_meta(get_current_user_id(),'zcc_last_seen',time());}
 public function menus(){$p=Permissions::instance();if(!$p->is_zcc_user())return;$cap=is_super_admin()?'manage_network_options':'read';add_menu_page('ZinControlCenter NextGen','ZinControlCenter','read','zccng-home',[$this,'home'],'dashicons-admin-multisite',2);if($p->workspace('nexus'))add_submenu_page('zccng-home','Network Command','Network Command',$cap,'zccng-command-nexus',[$this,'nexus']);if($p->workspace('operations'))add_submenu_page('zccng-home','Operations Command','Operations Command','read','zccng-operations',[$this,'operations']);if($p->workspace('staff'))add_submenu_page('zccng-home','Staff Hub','Staff Hub','read','zccng-staff-hub',[$this,'staff']);if($p->workspace('profile'))add_submenu_page('zccng-home','My Profile','My Profile','read','zccng-profile',[$this,'profile']);if($p->workspace('support'))add_submenu_page('zccng-home','Support Command','Support Command','read','zccng-support',[$this,'support']);if($p->workspace('hr'))add_submenu_page('zccng-home','HR Command','HR Command','read','zccng-hr',[$this,'hr']);remove_submenu_page('zccng-home','zccng-home');}
 public function settings_menu(){if(is_super_admin())add_submenu_page('settings.php','NextGen Settings','NextGen Settings','manage_network_options','zccng-settings',[$this,'settings']);}
 public function settings(){if(!current_user_can('manage_network_options'))wp_die('Permission denied',403);$layout=$this->clock_layout();?><div class="wrap"><h1>NextGen Settings</h1><form method="post" action="<?php echo esc_url(network_admin_url('edit.php?action=zccng_save_settings'));?>"><?php wp_nonce_field('zccng_settings');?><table class="form-table"><tr><th>Staff clock layout</th><td><select name="clock_layout"><option value="spotlight" <?php selected($layout,'spotlight');?>>Spotlight</option><option value="split" <?php selected($layout,'split');?>>Split</option><option value="compact" <?php selected($layout,'compact');?>>Compact</option></select></td></tr><tr><th>Ticker direction</th><td><select name="ticker_direction"><option value="rtl">Right to left</option><option value="ltr">Left to right</option><option value="ttb">Top to bottom</option><option value="btt">Bottom to top</option><option value="static">Static</option></select></td></tr><tr><th>Ticker position</th><td><select name="ticker_position"><option value="top">Top</option><option value="below_bar">Below command bar</option><option value="content">Above workspace content</option><option value="bottom">Bottom</option><option value="fixed_top">Fixed top</option><option value="fixed_bottom">Fixed bottom</option></select></td></tr><tr><th>Ticker timing</th><td><input type="number" min="5" max="120" name="ticker_speed" value="32"> seconds &nbsp; <input type="number" min="1" max="30" name="ticker_delay" value="5"> second rotation delay</td></tr><tr><th>Immersive interface</th><td><label><input type="checkbox" name="immersive" value="1" <?php checked((int)get_site_option('zccng_immersive_mode',1),1);?>> Hide unrelated WordPress menus for non-Super-Admin NextGen staff</label></td></tr></table><?php submit_button();?></form></div><?php }
 public function save_settings(){if(!current_user_can('manage_network_options'))wp_die('Permission denied',403);check_admin_referer('zccng_settings');$layout=sanitize_key($_POST['clock_layout']??'split');update_site_option('zccng_clock_layout',in_array($layout,['spotlight','split','compact'],true)?$layout:'split');update_site_option('zccng_immersive_mode',isset($_POST['immersive'])?1:0);$dir=sanitize_key($_POST['ticker_direction']??'rtl');update_site_option('zccng_ticker_direction',in_array($dir,['rtl','ltr','ttb','btt','static'],true)?$dir:'rtl');$pos=sanitize_key($_POST['ticker_position']??'top');update_site_option('zccng_ticker_position',in_array($pos,['top','below_bar','content','bottom','fixed_top','fixed_bottom'],true)?$pos:'top');update_site_option('zccng_ticker_speed',max(5,min(120,absint($_POST['ticker_speed']??32))));update_site_option('zccng_ticker_delay',max(1,min(30,absint($_POST['ticker_delay']??5))));wp_safe_redirect(network_admin_url('settings.php?page=zccng-settings&updated=1'));exit;}
 private function clock_layout(){$v=sanitize_key((string)get_site_option('zccng_clock_layout','split'));return in_array($v,['spotlight','split','compact'],true)?$v:'split';}
 public function assets($hook){if(strpos((string)$hook,'zccng')===false)return;wp_enqueue_style('zccng-app',ZCCNG_URL.'assets/css/app.css',[],ZCCNG_VERSION);wp_enqueue_script('zccng-app',ZCCNG_URL.'assets/js/app.js',[],ZCCNG_VERSION,true);wp_localize_script('zccng-app','ZCCNG',['rest'=>esc_url_raw(rest_url('zccng/v1/')),'nonce'=>wp_create_nonce('wp_rest'),'timezone'=>wp_timezone_string()?:'UTC','tickerDirection'=>get_site_option('zccng_ticker_direction','rtl'),'tickerPosition'=>get_site_option('zccng_ticker_position','top'),'tickerSpeed'=>(int)get_site_option('zccng_ticker_speed',32),'tickerDelay'=>(int)get_site_option('zccng_ticker_delay',5)]);}
 public function immersive(){if(is_super_admin()||!get_site_option('zccng_immersive_mode',1)||!Permissions::instance()->is_zcc_user())return;global $menu;foreach((array)$menu as $item){$slug=$item[2]??'';if($slug!=='zccng-home')remove_menu_page($slug);}}
 public function admin_bar($bar){if(is_super_admin()||!get_site_option('zccng_immersive_mode',1)||!Permissions::instance()->is_zcc_user())return;foreach(['wp-logo','site-name','updates','comments','new-content','my-sites','search'] as $id)$bar->remove_node($id);}
 private function landing_for($user){if(!$user instanceof \WP_User)return admin_url();if(is_super_admin($user->ID)||user_can($user,'zccng_access_nexus'))return admin_url('admin.php?page=zccng-command-nexus');if(user_can($user,'zccng_access_operations'))return admin_url('admin.php?page=zccng-operations');if(user_can($user,'zccng_access_hr'))return admin_url('admin.php?page=zccng-hr');if(user_can($user,'zccng_access_support'))return admin_url('admin.php?page=zccng-support');if(user_can($user,'zccng_access_staff_hub'))return admin_url('admin.php?page=zccng-staff-hub');if(user_can($user,'zccng_access_profile'))return admin_url('admin.php?page=zccng-profile');return admin_url();}
 public function login_redirect($to,$requested,$user){return is_wp_error($user)||!$user instanceof \WP_User?$to:$this->landing_for($user);}
 public function dashboard_redirect(){if(!is_user_logged_in()||wp_doing_ajax()||(defined('REST_REQUEST')&&REST_REQUEST))return;if(isset($_GET['zccng_main_admin'])&&'1'===sanitize_text_field(wp_unslash($_GET['zccng_main_admin']))&&(is_super_admin()||current_user_can('zccng_access_nexus'))&&check_admin_referer('zccng_main_admin'))return;global $pagenow;if($pagenow==='index.php'&&!isset($_GET['page'])&&Permissions::instance()->is_zcc_user()){wp_safe_redirect($this->landing_for(wp_get_current_user()));exit;}}
 public function home(){foreach(['nexus','operations','staff','profile','support','hr'] as $w)if(Permissions::instance()->workspace($w)){$this->{$w}();return;}wp_die('No workspace assigned',403);}
 private function shell($w,$title,$sub,$icon,$content){$p=Permissions::instance();$theme=get_user_meta(get_current_user_id(),'zccng_theme',true)?:'cloud-nexus';?><div class="zccng-app" data-theme="<?php echo esc_attr($theme);?>" data-workspace="<?php echo esc_attr($w);?>"><aside class="zccng-rail"><a class="zccng-brand" href="<?php echo esc_url($this->landing_for(wp_get_current_user()));?>"><?php echo Icons::render('nexus');?><span>ZinControlCenter <b>NextGen</b></span></a><nav><?php foreach([['nexus','zccng-command-nexus','Network Command'],['operations','zccng-operations','Operations Command'],['staff','zccng-staff-hub','Staff Hub'],['profile','zccng-profile','My Profile'],['support','zccng-support','Support Command'],['hr','zccng-hr','HR Command']] as $l)if($p->workspace($l[0]))echo '<a class="'.($w===$l[0]?'is-active':'').'" href="'.esc_url(admin_url('admin.php?page='.$l[1])).'">'.Icons::render($l[0]).'<span>'.esc_html($l[2]).'</span></a>';?></nav></aside><main class="zccng-main"><?php echo Communications::render_ticker();?><header class="zccng-top"><button class="zccng-search" type="button" data-command-open><?php echo Icons::render('analytics');?><span>Search the network...</span><kbd>Ctrl K</kbd></button><div class="zccng-top-actions"><button class="zccng-button zccng-button--light" type="button" data-edit-layout>Edit layout</button><select data-theme-picker><option value="celestial-midnight">Celestial Midnight</option><option value="nebula-glass">Nebula Glass</option><option value="quantum-command">Quantum Command</option><option value="celestial-daylight">Celestial Daylight</option><option value="cloud-nexus">Cloud Nexus</option><option value="solar-command">Solar Command</option></select></div></header><section class="zccng-content" data-layout-root data-workspace="<?php echo esc_attr($w);?>"><div class="zccng-hero"><div><small>CELESTIAL NEXUS</small><h1><?php echo esc_html($title);?></h1><p><?php echo esc_html($sub);?></p></div><div class="zccng-orbit"><?php echo Icons::render($icon);?><span>Live</span></div></div><?php echo $content;?></section></main><div class="zccng-command" hidden><div class="zccng-command-panel"><input type="search" placeholder="Search workspaces and commands"><div class="zccng-command-results"></div></div></div></div><?php }
 private function kpis($items){echo '<div class="zccng-kpis">';foreach($items as $i)echo '<article class="zccng-kpi zccng-accent--'.esc_attr($i[3]).'"><span>'.esc_html($i[0]).'</span><strong>'.esc_html($i[1]).'</strong><small>'.esc_html($i[2]).'</small></article>';echo '</div>';}
 private function widgets($w,$items){echo '<div class="zccng-section-title"><div><h2>Command Dashboard</h2><p>Drag, pin, focus, collapse, and save role-approved intelligence widgets.</p></div><button class="zccng-button" type="button" data-save-layout>Save layout</button></div><div class="zccng-widgets" data-widget-grid data-workspace="'.esc_attr($w).'">';foreach($items as $i)echo '<article class="zccng-widget" draggable="false" data-widget="'.esc_attr(sanitize_title($i[0])).'"><header><span class="zccng-drag">⋮⋮</span>'.Icons::render($i[2]).'<h3>'.esc_html($i[0]).'</h3><button type="button" data-widget-pin aria-label="Pin widget" title="Pin widget">⌖</button><button type="button" data-widget-modal aria-label="Open widget in focus window" title="Open in focus window">□</button><button type="button" data-widget-collapse aria-label="Collapse widget" title="Collapse widget">−</button></header><div class="zccng-widget-body"><div class="zccng-live-line"><i></i><span>Live data source</span></div><p>'.esc_html($i[1]).'</p></div></article>';echo '</div>';}
 private function panel($t,$h){$id=sanitize_title($t);$map=['Smart Form Builder'=>'forms','Assign Form'=>'forms','Form Submissions'=>'forms','Create Candidate'=>'candidates','Candidate Email Status'=>'candidates','Submissions & Status'=>'candidates','Workforce Lifecycle Manager'=>'workforce','Recently Updated Staff'=>'workforce','Document Review Queue'=>'documents','Archive Record Manager'=>'archive','Archive Directory'=>'archive','Academy Course Builder'=>'training','Training Assignment'=>'training','Training Review Queue'=>'training','Knowledge Publisher'=>'knowledge','Knowledge Library Manager'=>'knowledge','Employment Email'=>'communications'];$group=$map[$t]??'overview';echo '<section data-hr-section="'.esc_attr($group).'" class="zccng-panel zccng-layout-item" draggable="false" data-widget="'.esc_attr($id).'"><header><span class="zccng-drag" aria-hidden="true">⋮⋮</span><h2>'.esc_html($t).'</h2><button type="button" data-widget-pin aria-label="Pin widget" title="Pin widget">⌖</button><button type="button" data-widget-modal aria-label="Open widget in focus window" title="Open in focus window">□</button><button type="button" data-widget-collapse aria-label="Collapse widget" title="Collapse widget">−</button></header><div class="zccng-panel-body">'.$h.'</div></section>'; }
 private function people($users,$empty){if(!$users)return '<div class="zccng-empty">'.esc_html($empty).'</div>';$o='<div class="zccng-people">';foreach($users as $u)$o.='<div><img src="'.esc_url(get_avatar_url($u->ID,['size'=>64])).'" alt=""><span><b>'.esc_html($u->display_name).'</b><small>'.esc_html(implode(', ',$u->roles??[])).'</small></span></div>';return $o.'</div>';}
 private function leave($rows){if(!$rows)return '<div class="zccng-empty">No leave records are available.</div>';$o='<div class="zccng-list">';foreach($rows as $r)$o.='<div><b>'.esc_html(ucwords(str_replace('_',' ',$r['leave_type']??'Leave'))).'</b><span>'.esc_html(($r['start_date']??'').' to '.($r['end_date']??'')).'</span><em>'.esc_html($r['status']??'Approved').'</em></div>';return $o.'</div>';}
 public function nexus(){Permissions::instance()->require_workspace('nexus');$d=Repository::network_summary();ob_start();$this->kpis([['Network Sites',$d['sites'],'Live network source','cyan'],['Active Sites',$d['active_sites'],'Live network source','green'],['Network Users',$d['users'],'Live network source','violet'],['Connected Sites',$d['connected_sites'],'Approved connected sites','amber']]);$this->widgets('nexus',[['Network Health','Current WordPress Multisite availability and totals.','nexus'],['Site Command','Connected-site operational information.','analytics'],['Governance Radar','Role-scoped governance and access overview.','governance'],['Release Readiness','Platform release and installation status.','recovery']]);$activity='';foreach(Repository::recent_activity() as $a){$u=get_userdata((int)$a['user_id']);$activity.='<div><b>'.esc_html($u?$u->display_name:'System').'</b><span>'.esc_html($a['summary']?:ucwords(str_replace('_',' ',$a['event_type']))).'</span><em>'.esc_html(get_date_from_gmt($a['created_at'],get_option('date_format').' '.get_option('time_format'))).'</em></div>';}$this->panel('Recent Activity',$activity?'<div class="zccng-list">'.$activity.'</div>':'<div class="zccng-empty">No activity has been recorded yet.</div>');$this->shell('nexus','Network Command Nexus','Role-scoped command, intelligence, governance, and network operations.','nexus',ob_get_clean());}
 public function staff(){Permissions::instance()->require_workspace('staff');$d=Repository::staff_summary();ob_start();$this->kpis([['All Staff',$d['staff_count'],'WordPress user accounts','violet'],['Online Now',$d['online_count'],'Seen within 15 minutes','cyan'],['Working',$d['working_count'],'Clocked in or on break','green'],['On Leave',$d['leave_count'],'Approved current leave','amber']]);$is_candidate=in_array('zccng_candidate',(array)wp_get_current_user()->roles,true);if($is_candidate){$this->panel('Candidate Application',Candidates::render_candidate_home(get_current_user_id()));}else{$layout=$this->clock_layout();$clock='<div class="zccng-timeclock zccng-clock-layout--'.esc_attr($layout).'" data-staff-clock><div class="zccng-analog"><span class="n12">12</span><span class="n3">3</span><span class="n6">6</span><span class="n9">9</span><i class="zccng-hand zccng-hour" data-clock-hour></i><i class="zccng-hand zccng-minute" data-clock-minute></i><i class="zccng-hand zccng-second" data-clock-second></i><b class="zccng-clock-pin"></b></div><div class="zccng-clock-info"><strong data-clock-digital>--:--:--</strong><span data-clock-date></span><div class="zccng-presence zccng-presence--available" data-presence><span class="zccng-presence-beacon" aria-hidden="true"></span><div><small>Availability</small><strong data-presence-label>Available</strong></div></div><p class="zccng-clock-state">Shift: <b data-clock-status>Loading</b><span class="zccng-clock-led" data-clock-led aria-hidden="true"></span></p><div class="zccng-shift-metrics"><span>Today <b data-hours-today>0h 00m</b></span><span>This week <b data-hours-week>0h 00m</b></span><span>Last shift <b data-hours-last>0h 00m</b></span></div><label class="zccng-status-control">Availability <select data-availability><option value="available">Available</option><option value="busy">Busy</option><option value="in_meeting">In Meeting</option><option value="on_break">On Break</option><option value="offline">Offline</option></select></label><button class="zccng-button" type="button" data-clock-action>Clock In</button><small data-clock-message></small></div></div>';$this->panel('Clock In / Clock Out',$clock);}echo '<div class="zccng-grid zccng-grid--2">';$this->panel('Online Staff',$this->people($d['online'],'No staff have been seen online recently.'));$this->panel('Currently Working',$this->people($d['working'],'No staff are currently clocked in.'));$this->panel('Current Leave',$this->leave($d['leave']));$dir=current_user_can('list_users')?admin_url('users.php'):admin_url('admin.php?page=zccng-staff-hub');$this->panel('Staff Directory','<p>Browse staff accounts and role information.</p><a class="zccng-button" href="'.esc_url($dir).'">Open staff directory</a>');echo '</div>';$this->panel('My Work Email',Workforce_Mail::render_staff_panel());$this->panel('Knowledge Center',Knowledge::render_center());$this->panel('Workforce Academy',Academy::render_mine());$this->panel('Security & Scam Watch',Security::render_watch());$inbox=Repository::communications_inbox(get_current_user_id(),10);$this->panel('Workforce Inbox',$this->communications_list($inbox));$doc_upload='<form class="zccng-broadcast-form" method="post" enctype="multipart/form-data" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="zccng_document_upload">'.wp_nonce_field('zccng_document_upload','_wpnonce',true,false).'<label>Document title<input name="title" required></label><label>Category<select name="category">';foreach(Documents::categories() as $k=>$v)$doc_upload.='<option value="'.esc_attr($k).'">'.esc_html($v).'</option>';$doc_upload.='</select></label><label>Document<input type="file" name="document_file" accept=".pdf,.doc,.docx,.txt,.jpg,.jpeg,.png" required></label><button class="zccng-button" type="submit">Upload document</button></form>';$this->panel('My Documents',Documents::render_mine().$doc_upload);$this->panel('Assigned Forms',Forms::render_user_forms(get_current_user_id()));$this->shell('staff','Staff Hub','Live staff availability, working status, leave, and directory access.','staff',ob_get_clean());}
 public function profile(){Permissions::instance()->require_workspace('profile');$d=Repository::profile(get_current_user_id());ob_start();echo '<section class="zccng-profile-head"><img src="'.esc_url($d['avatar']).'" alt=""><div><small>PERSONAL COMMAND PROFILE</small><h2>'.esc_html($d['name']).'</h2><p>'.esc_html(implode(', ',$d['roles'])).' · '.esc_html($d['hr']['department']??'Department not assigned').'</p></div><a class="zccng-button" href="'.esc_url(admin_url('profile.php')).'">Edit WordPress profile</a></section>';$this->panel('My Workforce Lifecycle',Lifecycle::render_identity(get_current_user_id()));$this->kpis([['Hours This Week',number_format_i18n($d['hours_week'],1),'Live timesheet total','cyan'],['Unread Alerts',$d['unread'],'Personal notifications','rose'],['Shift',ucwords(str_replace('_',' ',$d['clock_status']?:'not clocked in')),'Current staff state','green'],['Leave Requests',count($d['leave']),'Recent personal requests','amber']]);echo '<div class="zccng-grid zccng-grid--2">';$this->panel('Employment','<dl class="zccng-detail"><dt>Job title</dt><dd>'.esc_html($d['hr']['job_title']??'Not assigned').'</dd><dt>Employment type</dt><dd>'.esc_html($d['hr']['employment_type']??'Not assigned').'</dd><dt>Hire date</dt><dd>'.esc_html($d['hr']['hire_date']??'Not recorded').'</dd><dt>Email</dt><dd>'.esc_html($d['email']).'</dd></dl>');$this->panel('Recent Leave',$this->leave($d['leave']));echo '</div>';$this->panel('My Documents',Documents::render_mine());$this->panel('My Forms',Forms::render_user_forms(get_current_user_id()));$this->panel('My Training',Academy::render_mine());$this->panel('My Work Email',Workforce_Mail::render_staff_panel());$this->panel('My Communications',$this->communications_list(Repository::communications_inbox(get_current_user_id(),20)));$this->shell('profile','My Profile Command Center','Personal identity, timesheet, leave, and notification intelligence.','profile',ob_get_clean());}
 public function support(){Permissions::instance()->require_workspace('support');$d=Repository::support_summary();ob_start();$this->kpis([['Open Tickets',$d['open'],'Role-visible queue','cyan'],['In Progress',$d['progress'],'Active work','violet'],['Critical',$d['critical'],'Requires priority','rose'],['SLA Breaches',$d['breached'],'Past service deadline','amber']]);if(!$d['available'])$html='<div class="zccng-empty">The support ticket data source is not installed yet.</div>';elseif(!$d['tickets'])$html='<div class="zccng-empty">No open tickets are visible to this role.</div>';else{$rows='';foreach($d['tickets'] as $t)$rows.='<tr><td>'.esc_html($t['ticket_number']?:'#'.$t['id']).'</td><td>'.esc_html($t['subject']).'</td><td>'.esc_html($t['priority']).'</td><td>'.esc_html($t['status']).'</td></tr>';$html='<div class="zccng-table-wrap"><table><thead><tr><th>Ticket</th><th>Subject</th><th>Priority</th><th>Status</th></tr></thead><tbody>'.$rows.'</tbody></table></div>';}$this->panel('Priority Ticket Queue',$html);$this->shell('support','Support Command Center','Live ticket health, SLA risk, and role-visible queues.','support',ob_get_clean());}
 private function communications_list($rows){if(!$rows)return '<div class="zccng-empty">No communications are available.</div>';$o='<div class="zccng-communications-list">';foreach($rows as $r)$o.='<article class="zccng-alert zccng-alert--'.esc_attr($r['priority']).'"><span class="zccng-alert-beacon" aria-hidden="true"></span><div><small>'.esc_html(ucwords($r['category'])).'</small><h3>'.esc_html($r['title']).'</h3><p>'.esc_html($r['message']).'</p><div class="zccng-message-actions">'.(!$r['is_read']?'<a href="'.esc_url(wp_nonce_url(admin_url('admin-post.php?action=zccng_message_action&do=read&id='.(int)$r['id']),'zccng_message_'.(int)$r['id'])).'">Mark read</a> ':'').(!$r['is_acknowledged']?'<a href="'.esc_url(wp_nonce_url(admin_url('admin-post.php?action=zccng_message_action&do=acknowledge&id='.(int)$r['id']),'zccng_message_'.(int)$r['id'])).'">Acknowledge</a> ':'').'<a href="'.esc_url(wp_nonce_url(admin_url('admin-post.php?action=zccng_message_action&do=archive&id='.(int)$r['id']),'zccng_message_'.(int)$r['id'])).'">Archive</a></div></div></article>';return $o.'</div>';}
